class HYV4VLVideoProcessorInitKwargs(VideosKwargs, total=False):
    r"""
    size (`dict[str, int]`, *optional*):
        Minimum per-frame pixel area (`shortest_edge`) and total clip pixel budget (`longest_edge`).
    patch_size (`int`, *optional*, defaults to 16):
        The spatial patch size of the vision encoder.
    temporal_patch_size (`int`, *optional*, defaults to 1):
        The temporal patch size of the vision encoder.
    merge_size (`int`, *optional*, defaults to 2):
        The merge size of the vision encoder to llm encoder.
    min_frames (`int`, *optional*, defaults to 2):
        The minimum number of frames to sample from a video.
    max_frames (`int`, *optional*, defaults to 1024):
        The maximum number of frames to sample from a video.
    max_image_size (`dict[str, int]`, *optional*):
        Per-frame pixel-area limit, specified by the `longest_edge` key.
    """

    patch_size: int
    temporal_patch_size: int
    merge_size: int
    min_frames: int
    max_frames: int
    max_image_size: dict[str, int]


def smart_resize(
    num_frames: int,
    height: int,
    width: int,
    factor: int,
    min_pixels: int,
    max_pixels: int,
    max_image_size: int,
) -> tuple[int, int]:
    """Resize a frame under both the clip's pixel budget and the per-frame area limit."""
    if min(num_frames, height, width, factor, min_pixels, max_pixels, max_image_size) <= 0:
        raise ValueError("Video dimensions, resize factor, and pixel budgets must be positive.")
    if max(height, width) / min(height, width) > 200:
        raise ValueError(
            f"absolute aspect ratio must be smaller than 200, got {max(height, width) / min(height, width)}"
        )
    per_frame_budget = min(max_pixels / num_frames, max_image_size)
    min_cells = math.ceil(min_pixels / factor**2)
    max_cells = math.floor(per_frame_budget / factor**2)
    if min_cells > max_cells:
        raise ValueError("The video pixel budget cannot fit a factor-aligned frame at the minimum pixel area.")

    h_bar = max(factor, round(height / factor) * factor)
    w_bar = max(factor, round(width / factor) * factor)
    if h_bar * w_bar > per_frame_budget:
        beta = math.sqrt((height * width) / per_frame_budget)
        h_bar = max(factor, math.floor(height / beta / factor) * factor)
        w_bar = max(factor, math.floor(width / beta / factor) * factor)
    elif h_bar * w_bar < min_pixels:
        beta = math.sqrt(min_pixels / (height * width))
        h_bar = math.ceil(height * beta / factor) * factor
        w_bar = math.ceil(width * beta / factor) * factor

    if min_pixels <= h_bar * w_bar <= per_frame_budget:
        return h_bar, w_bar

    # Only repair boundary cases where clamping or rounding violated the area limits.
    # Enumerate the shorter grid edge to find a feasible shape close to the input aspect ratio.
    candidates = []
    for short_edge in range(1, math.isqrt(max_cells) + 1):
        lower = max(short_edge, math.ceil(min_cells / short_edge))
        upper = max_cells // short_edge
        if lower <= upper:
            long_edge = min(upper, max(lower, round(short_edge * max(height, width) / min(height, width))))
            grid_h, grid_w = (short_edge, long_edge) if height <= width else (long_edge, short_edge)
            candidates.append((grid_h, grid_w))
    grid_h, grid_w = min(
        candidates, key=lambda grid: (abs(math.log(grid[0] * width / (grid[1] * height))), -grid[0] * grid[1])
    )
    return grid_h * factor, grid_w * factor


@auto_docstring
class HYV4VLVideoProcessor(BaseVideoProcessor):
    resample = PILImageResampling.BICUBIC
    size = {"shortest_edge": 4096, "longest_edge": 33554432}
    image_mean = IMAGENET_STANDARD_MEAN
    image_std = IMAGENET_STANDARD_STD
    do_resize = True
    do_rescale = True
    do_normalize = True
    do_convert_rgb = True
    patch_size = 16
    temporal_patch_size = 1
    merge_size = 2
    min_frames = 2
    max_frames = 1024
    do_sample_frames = False
    valid_kwargs = HYV4VLVideoProcessorInitKwargs
    model_input_names = ["pixel_values_videos", "video_grid_thw"]
    max_image_size = {"longest_edge": 1024 * 1024}
    max_duration = None
    num_frames = None
    fps = 2

    def __init__(self, **kwargs: Unpack[HYV4VLVideoProcessorInitKwargs]):
        super().__init__(**kwargs)

    def sample_frames(
        self,
        metadata: VideoMetadata,
        num_frames: int | None = None,
        fps: int | float | None = None,
        **kwargs,
    ):
        """
        Default sampling function which uniformly samples the desired number of frames between 0 and total number of frames.
        If `fps` is passed along with metadata, `fps` frames per second are sampled uniformty. Arguments `num_frames`
        and `fps` are mutually exclusive.

        Args:
            video (`torch.Tensor`):
                Video that need to be sampled.
            metadata (`VideoMetadata`):
                Metadata of the video containing information about total duration, fps and total number of frames.
            num_frames (`int`, *optional*):
                Maximum number of frames to sample. Defaults to `self.num_frames`.
            fps (`int` or `float`, *optional*):
                Target frames to sample per second. Defaults to `self.fps`.
        Returns:
            np.ndarray: Sampled video frames.
        """
        if fps is not None and num_frames is not None:
            raise ValueError("`num_frames` and `fps` are mutually exclusive arguments, please use only one!")

        total_num_frames = metadata.total_num_frames
        fps = fps if fps is not None else self.fps

        # If num_frames is not given but fps is, calculate num_frames from fps
        if num_frames is None and fps is not None:
            if metadata.fps is None:
                metadata.fps = 24
                logger.warning_once(
                    "Asked to sample `fps` frames per second but no video metadata was provided which is required when sampling with `fps`. "
                    "Defaulting to `fps=24`. Please provide `video_metadata` for more accurate results."
                )
            num_frames = int(total_num_frames / metadata.fps * fps)
            num_frames = min(max(num_frames, self.min_frames), self.max_frames, total_num_frames)

        if num_frames is None:
            num_frames = min(max(total_num_frames, self.min_frames), self.max_frames)

        indices = np.linspace(0, total_num_frames - 1, num_frames).round().astype(int)

        return indices

    def resize(
        self,
        videos: "torch.Tensor",
        size: SizeDict,
        resample: "PILImageResampling | tvF.InterpolationMode | int | None",
        factor: int,
        max_image_size: dict[str, int],
        **kwargs,
    ) -> "torch.Tensor":
        """Resize dynamically based on input video aspect ratio."""
        if not size.shortest_edge or not size.longest_edge:
            raise ValueError(f"`size` dict must contain 'shortest_edge' and 'longest_edge' keys but got {size}.")
        height, width = smart_resize(
            num_frames=videos.shape[1],
            height=videos.shape[-2],
            width=videos.shape[-1],
            factor=factor,
            min_pixels=size.shortest_edge,
            max_pixels=size.longest_edge,
            max_image_size=max_image_size["longest_edge"],
        )
        return super().resize(
            image=videos,
            size=SizeDict(height=height, width=width),
            resample=resample,
        )

    def patchify(
        self,
        videos: "torch.Tensor",
        patch_size: int,
        merge_size: int,
        temporal_patch_size: int,
    ) -> tuple["torch.Tensor", int, int, int]:
        batch_size, num_frames, channel, resized_height, resized_width = videos.shape
        if pad := -num_frames % temporal_patch_size:
            videos = torch.cat((videos, videos[:, -1:].expand(-1, pad, -1, -1, -1)), dim=1)
            num_frames += pad

        grid_t = num_frames // temporal_patch_size
        grid_h, grid_w = resized_height // patch_size, resized_width // patch_size
        patches = videos.view(
            batch_size,
            grid_t,
            temporal_patch_size,
            channel,
            grid_h // merge_size,
            merge_size,
            patch_size,
            grid_w // merge_size,
            merge_size,
            patch_size,
        )
        # Key difference: row-major order within each merged block, as in the image processor
        patches = patches.permute(0, 1, 4, 5, 7, 8, 3, 2, 6, 9)
        flatten_patches = patches.reshape(
            batch_size,
            grid_t * grid_h * grid_w,
            channel * temporal_patch_size * patch_size * patch_size,
        )
        return flatten_patches, grid_t, grid_h, grid_w

    def _preprocess(
        self,
        videos: list["torch.Tensor"],
        do_resize: bool,
        size: SizeDict,
        resample: "PILImageResampling | tvF.InterpolationMode | int | None",
        do_rescale: bool,
        rescale_factor: float,
        do_normalize: bool,
        image_mean: float | list[float] | None,
        image_std: float | list[float] | None,
        max_image_size: dict[str, int],
        patch_size: int | None = None,
        temporal_patch_size: int | None = None,
        merge_size: int | None = None,
        return_tensors: str | TensorType | None = None,
        **kwargs,
    ):
        grouped_videos, grouped_videos_index = group_videos_by_shape(videos)
        resized_videos_grouped = {}
        for shape, stacked_videos in grouped_videos.items():
            if do_resize:
                stacked_videos = self.resize(
                    videos=stacked_videos,
                    size=size,
                    resample=resample,
                    factor=patch_size * merge_size,
                    max_image_size=max_image_size,
                )
            resized_videos_grouped[shape] = stacked_videos
        resized_videos = reorder_videos(resized_videos_grouped, grouped_videos_index)

        grouped_videos, grouped_videos_index = group_videos_by_shape(resized_videos)
        processed_videos_grouped = {}
        processed_grids = {}
        for shape, stacked_videos in grouped_videos.items():
            stacked_videos = self.rescale_and_normalize(
                stacked_videos, do_rescale, rescale_factor, do_normalize, image_mean, image_std
            )
            patches, grid_t, grid_h, grid_w = self.patchify(
                stacked_videos,
                patch_size=patch_size,
                merge_size=merge_size,
                temporal_patch_size=temporal_patch_size,
            )
            processed_videos_grouped[shape] = patches
            processed_grids[shape] = [[grid_t, grid_h, grid_w]] * len(stacked_videos)

        processed_videos = reorder_videos(processed_videos_grouped, grouped_videos_index)
        processed_grids = reorder_videos(processed_grids, grouped_videos_index)
        return BatchFeature(
            data={
                "pixel_values_videos": torch.cat(processed_videos, dim=0),
                "video_grid_thw": torch.tensor(processed_grids),
            },
            tensor_type=return_tensors,
        )

    def get_num_of_video_patches(
        self, num_frames: int, height: int, width: int, videos_kwargs=None, *, return_grid: bool = False
    ) -> int | tuple[int, int, int, int]:
        """
        A utility that returns number of video patches a given video size.

        Args:
            num_frames (`int`):
                Number of frames in the input video.
            height (`int`):
                Height of the input video.
            width (`int`):
                Width of the input video.
            videos_kwargs (`dict`, *optional*)
                Any kwargs to override defaults of the video processor.
            return_grid (`bool`, *optional*, defaults to `False`):
                Whether to also return the temporal, height and width grid of the patches.
        Returns:
            `int`: Number of video patches per video, or `tuple[int, int, int, int]` with the number of patches and
            the `(grid_t, grid_h, grid_w)` grid if `return_grid=True`.
        """
        videos_kwargs = videos_kwargs if videos_kwargs is not None else {}
        do_resize = videos_kwargs.get("do_resize", None)
        do_resize = do_resize if do_resize is not None else self.do_resize
        size = videos_kwargs.get("size", None) or self.size
        min_pixels = size["shortest_edge"]
        max_pixels = size["longest_edge"]
        max_image_size = videos_kwargs.get("max_image_size", None) or self.max_image_size
        patch_size = videos_kwargs.get("patch_size", None) or self.patch_size
        merge_size = videos_kwargs.get("merge_size", None) or self.merge_size
        temporal_patch_size = videos_kwargs.get("temporal_patch_size", None) or self.temporal_patch_size

        factor = patch_size * merge_size
        if do_resize:
            height, width = smart_resize(
                num_frames=num_frames,
                height=height,
                width=width,
                factor=factor,
                min_pixels=min_pixels,
                max_pixels=max_pixels,
                max_image_size=max_image_size["longest_edge"],
            )

        grid_t = (num_frames + -num_frames % temporal_patch_size) // temporal_patch_size
        grid_h, grid_w = height // patch_size, width // patch_size
        num_patches = grid_t * grid_h * grid_w

        return (num_patches, grid_t, grid_h, grid_w) if return_grid else num_patches


